// ============================================================================
//  Render HTML to Folder  —  renders HTML you give it into a folder you name.
//
//  Input (from the form or from "Manual Input"), merged with Settings:
//    html           full HTML document, pasted            } one of the two
//    html_path      path to an .html file on the n8n host }
//    output_folder  absolute (/files/...) or relative to BASE_DIR
//    file_prefix    optional, default "slide_"
//    selector       optional, default from Settings (".slide")
//
//  Writes: source.html, <prefix>01.jpg, <prefix>02.jpg, ...
//  Paths are as n8n sees them inside its container, like LOCAL_OUTPUT_ROOT.
// ============================================================================
const fs = require('fs');
const s = $json;

let html = String(s.html || '').trim();
const htmlPath = String(s.html_path || '').trim();
if (!html && htmlPath) {
  try { html = fs.readFileSync(htmlPath, 'utf8'); }
  catch (e) { throw new Error('Could not read html_path "' + htmlPath + '": ' + e.message); }
}
if (!html) throw new Error('Give either "html" (pasted) or "html_path" (a file on the n8n host).');

let folder = String(s.output_folder || '').trim().replace(/[\\/]+$/, '');
if (!folder) throw new Error('"output_folder" is required.');
if (folder.split(/[\\/]/).includes('..')) throw new Error('"output_folder" may not contain "..".');
if (!folder.startsWith('/')) {
  folder = String(s.BASE_DIR || '/files/slides').replace(/[\\/]+$/, '') + '/' + folder;
}

const prefix = String(s.file_prefix || '').trim() || 'slide_';
if (!/^[A-Za-z0-9._-]+$/.test(prefix)) throw new Error('"file_prefix" may only use letters, digits, . _ and -');
const selector = String(s.selector || '').trim() || s.SELECTOR || '.slide';
const ext = String(s.SLIDE_FORMAT || 'jpeg').toLowerCase() === 'png' ? 'png' : 'jpg';

fs.mkdirSync(folder, { recursive: true });
fs.writeFileSync(`${folder}/source.html`, html);

const resp = await this.helpers.httpRequest({
  method: 'POST',
  url: s.RENDER_SERVICE_URL,
  body: {
    html,
    width: s.SLIDE_WIDTH,
    height: s.SLIDE_HEIGHT,
    deviceScale: s.DEVICE_SCALE,
    selector,
    format: s.SLIDE_FORMAT,
    quality: s.SLIDE_QUALITY,
  },
  json: true,
  timeout: 180000,
});

const images = (resp && resp.images) || [];
if (!images.length) throw new Error(`Renderer returned no images. Does the HTML contain elements matching "${selector}"?`);

// Remove earlier renders with the same prefix so a shorter carousel never
// leaves stale slides behind.
const esc = prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const old = new RegExp('^' + esc + '\\d+\\.(jpg|jpeg|png)$', 'i');
for (const f of fs.readdirSync(folder)) if (old.test(f)) fs.unlinkSync(`${folder}/${f}`);

const files = images.map((img, i) => {
  const b64 = typeof img === 'string' ? img : (img.image_base64 || img.base64 || img.data);
  const name = `${prefix}${String(i + 1).padStart(2, '0')}.${ext}`;
  fs.writeFileSync(`${folder}/${name}`, Buffer.from(String(b64 || ''), 'base64'));
  return name;
});

const fits = Array.isArray(resp.fits) ? resp.fits : [];
return [{
  json: {
    folder,
    slides_written: files.length,
    files,
    shrunk_slides: fits.map((f, i) => (f && f < 1 ? `${i + 1} (${Math.round(f * 100)}%)` : null)).filter(Boolean),
    slide_urls: Array.isArray(resp.urls) ? resp.urls : [],
  },
}];
